 45	GIT_INLINE(const cli_opt_spec *) spec_for_long(
 46		int *is_negated,
 47		int *has_value,
 48		const char **value,
 49		const cli_opt_parser *parser,
 50		const char *arg)
 51	{
 52		const cli_opt_spec *spec;
 53		const char *eql;
 54		size_t eql_pos;
 55	
 56		eql = strchr(arg, '=');
 57		eql_pos = (eql = strchr(arg, '=')) ? (size_t)(eql - arg) : strlen(arg);
 58	
 59		for (spec = parser->specs; spec->type; ++spec) {
 60			/* Handle -- (everything after this is literal) */
 61			if (spec->type == CLI_OPT_TYPE_LITERAL && arg[0] == '\0')
 62				return spec;
 63	
 64			/* Handle --no-option arguments for bool types */
 65			if (spec->type == CLI_OPT_TYPE_BOOL &&
 66			    strncmp(arg, "no-", 3) == 0 &&
 67			    strcmp(arg + 3, spec->name) == 0) {
 68				*is_negated = 1;
 69				return spec;
 70			}
 71	
 72			/* Handle the typical --option arguments */
 73			if (spec_is_option_type(spec) &&
 74			    spec->name &&
 75			    strcmp(arg, spec->name) == 0)
 76				return spec;
 77	
 78			/* Handle --option=value arguments */
 79			if (spec->type == CLI_OPT_TYPE_VALUE &&
 80			    spec->name && eql &&
 81			    strncmp(arg, spec->name, eql_pos) == 0 &&
 82			    spec->name[eql_pos] == '\0') {
 83				*has_value = 1;
 84				*value = arg[eql_pos + 1] ? &arg[eql_pos + 1] : NULL;
 85				return spec;
 86			}
 87		}
 88	
 89		return NULL;
 90	}
