 92	GIT_INLINE(const cli_opt_spec *) spec_for_short(
 93		const char **value,
 94		const cli_opt_parser *parser,
 95		const char *arg)
 96	{
 97		const cli_opt_spec *spec;
 98	
 99		for (spec = parser->specs; spec->type; ++spec) {
100			/* Handle -svalue short options with a value */
101			if (spec->type == CLI_OPT_TYPE_VALUE &&
102			    arg[0] == spec->alias &&
103			    arg[1] != '\0') {
104				*value = &arg[1];
105				return spec;
106			}
107	
108			/* Handle typical -s short options */
109			if (arg[0] == spec->alias) {
110				*value = NULL;
111				return spec;
112			}
113		}
114	
115		return NULL;
116	}
