118	GIT_INLINE(const cli_opt_spec *) spec_for_arg(cli_opt_parser *parser)
119	{
120		const cli_opt_spec *spec;
121		size_t args = 0;
122	
123		for (spec = parser->specs; spec->type; ++spec) {
124			if (spec->type == CLI_OPT_TYPE_ARG) {
125				if (args == parser->arg_idx) {
126					parser->arg_idx++;
127					return spec;
128				}
129	
130				args++;
131			}
132	
133			if (spec->type == CLI_OPT_TYPE_ARGS && args == parser->arg_idx)
134				return spec;
135		}
136	
137		return NULL;
138	}
