146	/*
147	 * If we have a choice with switches and bare arguments, and we see
148	 * the switch, then we no longer expect the bare argument.
149	 */
150	GIT_INLINE(void) consume_choices(const cli_opt_spec *spec, cli_opt_parser *parser)
151	{
152		/* back up to the beginning of the choices */
153		while (spec->type && (spec->usage & CLI_OPT_USAGE_CHOICE))
154			--spec;
155	
156		if (!spec_is_choice(spec))
157			return;
158	
159		do {
160			if (spec->type == CLI_OPT_TYPE_ARG)
161				parser->arg_idx++;
162			++spec;
163		} while(spec->type && (spec->usage & CLI_OPT_USAGE_CHOICE));
164	}
