224	static cli_opt_status_t parse_short(cli_opt *opt, cli_opt_parser *parser)
225	{
226		const cli_opt_spec *spec;
227		char *arg = parser->args[parser->idx++];
228		const char *value;
229	
230		opt->arg = arg;
231	
232		if ((spec = spec_for_short(&value, parser, &arg[1 + parser->in_short])) == NULL) {
233			opt->spec = NULL;
234			opt->status = CLI_OPT_STATUS_UNKNOWN_OPTION;
235			goto done;
236		}
237	
238		opt->spec = spec;
239	
240		if (spec->type == CLI_OPT_TYPE_BOOL && spec->value)
241			*((int *)spec->value) = 1;
242	
243		else if (spec->type == CLI_OPT_TYPE_ACCUMULATOR && spec->value)
244			*((int *)spec->value) += spec->switch_value ? spec->switch_value : 1;
245	
246		else if (spec->type == CLI_OPT_TYPE_SWITCH && spec->value)
247			*((int *)spec->value) = spec->switch_value;
248	
249		/* Parse values as "-ifoo" or "-i foo" */
250		else if (spec->type == CLI_OPT_TYPE_VALUE) {
251			if (value)
252				opt->value = (char *)value;
253			else if ((parser->idx + 1) <= parser->args_len)
254				opt->value = parser->args[parser->idx++];
255	
256			if (spec->value)
257				*((char **)spec->value) = opt->value;
258		}
259	
260		/*
261		 * Handle compressed short arguments, like "-fbcd"; see if there's
262		 * another character after the one we processed.  If not, advance
263		 * the parser index.
264		 */
265		if (spec->type != CLI_OPT_TYPE_VALUE && arg[2 + parser->in_short] != '\0') {
266			parser->in_short++;
267			parser->idx--;
268		} else {
269			parser->in_short = 0;
270		}
271	
272		/* Required argument was not provided */
273		if (spec->type == CLI_OPT_TYPE_VALUE &&
274		    !opt->value &&
275		    !(spec->usage & CLI_OPT_USAGE_VALUE_OPTIONAL))
276			opt->status = CLI_OPT_STATUS_MISSING_VALUE;
277		else
278			opt->status = CLI_OPT_STATUS_OK;
279	
280		consume_choices(opt->spec, parser);
281	
282	done:
283		return opt->status;
284	}
