286	static cli_opt_status_t parse_arg(cli_opt *opt, cli_opt_parser *parser)
287	{
288		const cli_opt_spec *spec = spec_for_arg(parser);
289	
290		opt->spec = spec;
291		opt->arg = parser->args[parser->idx];
292	
293		if (!spec) {
294			parser->idx++;
295			opt->status = CLI_OPT_STATUS_UNKNOWN_OPTION;
296		} else if (spec->type == CLI_OPT_TYPE_ARGS) {
297			if (spec->value)
298				*((char ***)spec->value) = &parser->args[parser->idx];
299	
300			/*
301			 * We have started a list of arguments; the remainder of
302			 * given arguments need not be examined.
303			 */
304			parser->in_args = (parser->args_len - parser->idx);
305			parser->idx = parser->args_len;
306			opt->args_len = parser->in_args;
307			opt->status = CLI_OPT_STATUS_OK;
308		} else {
309			if (spec->value)
310				*((char **)spec->value) = parser->args[parser->idx];
311	
312			parser->idx++;
313			opt->status = CLI_OPT_STATUS_OK;
314		}
315	
316		return opt->status;
317	}
