319	static int support_gnu_style(unsigned int flags)
320	{
321		if ((flags & CLI_OPT_PARSE_FORCE_GNU) != 0)
322			return 1;
323	
324		if ((flags & CLI_OPT_PARSE_GNU) == 0)
325			return 0;
326	
327		/* TODO: Windows */
328	#if defined(_WIN32) && defined(UNICODE)
329		if (_wgetenv(L"POSIXLY_CORRECT") != NULL)
330			return 0;
331	#else
332		if (getenv("POSIXLY_CORRECT") != NULL)
333			return 0;
334	#endif
335	
336		return 1;
337	}
