339	void cli_opt_parser_init(
340		cli_opt_parser *parser,
341		const cli_opt_spec specs[],
342		char **args,
343		size_t args_len,
344		unsigned int flags)
345	{
346		assert(parser);
347	
348		memset(parser, 0x0, sizeof(cli_opt_parser));
349	
350		parser->specs = specs;
351		parser->args = args;
352		parser->args_len = args_len;
353		parser->flags = flags;
354	
355		parser->needs_sort = support_gnu_style(flags);
