358	GIT_INLINE(const cli_opt_spec *) spec_for_sort(
359		int *needs_value,
360		const cli_opt_parser *parser,
361		const char *arg)
362	{
363		int is_negated, has_value = 0;
364		const char *value = NULL;
365		const cli_opt_spec *spec = NULL;
366		size_t idx = 0;
367	
368		*needs_value = 0;
369	
370		if (strncmp(arg, "--", 2) == 0) {
371			spec = spec_for_long(&is_negated, &has_value, &value, parser, &arg[2]);
372			*needs_value = !has_value;
373		}
374	
375		else if (strncmp(arg, "-", 1) == 0) {
376			spec = spec_for_short(&value, parser, &arg[1]);
377	
378			/*
379			 * Advance through compressed short arguments to see if
380			 * the last one has a value, eg "-xvffilename".
381			 */
382			while (spec && !value && arg[1 + ++idx] != '\0')
383				spec = spec_for_short(&value, parser, &arg[1 + idx]);
384	
385			*needs_value = (value == NULL);
386		}
387	
388		return spec;
389	}
