496	GIT_INLINE(int) spec_included(const cli_opt_spec **specs, const cli_opt_spec *spec)
497	{
498		const cli_opt_spec **i;
499	
500		for (i = specs; *i; ++i) {
501			if (spec == *i)
502				return 1;
503		}
504	
505		return 0;
506	}
