508	static cli_opt_status_t validate_required(
509		cli_opt *opt,
510		const cli_opt_spec specs[],
511		const cli_opt_spec **given_specs)
512	{
513		const cli_opt_spec *spec, *required;
514		int given;
515	
516		/*
517		 * Iterate over the possible specs to identify requirements and
518		 * ensure that those have been given on the command-line.
519		 * Note that we can have required *choices*, where one in a
520		 * list of choices must be specified.
521		 */
522		for (spec = specs, required = NULL, given = 0; spec->type; ++spec) {
523			if (!required && (spec->usage & CLI_OPT_USAGE_REQUIRED)) {
524				required = spec;
525				given = 0;
526			} else if (!required) {
527				continue;
528			}
529	
530			if (!given)
531				given = spec_included(given_specs, spec);
532	
533			/*
534			 * Validate the requirement unless we're in a required
535			 * choice.  In that case, keep the required state and
536			 * validate at the end of the choice list.
537			 */
538			if (!spec_is_choice(spec)) {
539				if (!given) {
540					opt->spec = required;
541					opt->status = CLI_OPT_STATUS_MISSING_ARGUMENT;
542					break;
543				}
544	
545				required = NULL;
546				given = 0;
547			}
548		}
549	
550		return opt->status;
551	}
