584	int cli_opt_foreach(
585		const cli_opt_spec specs[],
586		char **args,
587		size_t args_len,
588		unsigned int flags,
589		int (*callback)(cli_opt *, void *),
590		void *callback_data)
591	{
592		cli_opt_parser parser;
593		cli_opt opt;
594		int ret;
595	
596		cli_opt_parser_init(&parser, specs, args, args_len, flags);
597	
598		while (cli_opt_parser_next(&opt, &parser)) {
599			if ((ret = callback(&opt, callback_data)) != 0)
600				return ret;
601		}
602	
603		return 0;
604	}
