166	static cli_opt_status_t parse_long(cli_opt *opt, cli_opt_parser *parser)
167	{
168		const cli_opt_spec *spec;
169		char *arg = parser->args[parser->idx++];
170		const char *value = NULL;
171		int is_negated = 0, has_value = 0;
172	
173		opt->arg = arg;
174	
175		if ((spec = spec_for_long(&is_negated, &has_value, &value, parser, &arg[2])) == NULL) {
176			opt->spec = NULL;
177			opt->status = CLI_OPT_STATUS_UNKNOWN_OPTION;
178			goto done;
179		}
180	
181		opt->spec = spec;
182	
183		/* Future options parsed as literal */
184		if (spec->type == CLI_OPT_TYPE_LITERAL)
185			parser->in_literal = 1;
186	
187		/* --bool or --no-bool */
188		else if (spec->type == CLI_OPT_TYPE_BOOL && spec->value)
189			*((int *)spec->value) = !is_negated;
190	
191		/* --accumulate */
192		else if (spec->type == CLI_OPT_TYPE_ACCUMULATOR && spec->value)
193			*((int *)spec->value) += spec->switch_value ? spec->switch_value : 1;
194	
195		/* --switch */
196		else if (spec->type == CLI_OPT_TYPE_SWITCH && spec->value)
197			*((int *)spec->value) = spec->switch_value;
198	
199		/* Parse values as "--foo=bar" or "--foo bar" */
200		else if (spec->type == CLI_OPT_TYPE_VALUE) {
201			if (has_value)
202				opt->value = (char *)value;
203			else if ((parser->idx + 1) <= parser->args_len)
204				opt->value = parser->args[parser->idx++];
205	
206			if (spec->value)
207				*((char **)spec->value) = opt->value;
208		}
209	
210		/* Required argument was not provided */
211		if (spec->type == CLI_OPT_TYPE_VALUE &&
212		    !opt->value &&
213		    !(spec->usage & CLI_OPT_USAGE_VALUE_OPTIONAL))
214			opt->status = CLI_OPT_STATUS_MISSING_VALUE;
215		else
216			opt->status = CLI_OPT_STATUS_OK;
217	
218		consume_choices(opt->spec, parser);
219	
220	done:
221		return opt->status;
222	}
