286	static cli_opt_status_t parse_arg(cli_opt *opt, cli_opt_parser *parser)
287	{
288		const cli_opt_spec *spec = spec_for_arg(parser);
289	
290		opt->spec = spec;
291		opt->arg = parser->args[parser->idx];
