302			 * given arguments need not be examined.
303			 */
304			parser->in_args = (parser->args_len - parser->idx);
305			parser->idx = parser->args_len;
306			opt->args_len = parser->in_args;
307			opt->status = CLI_OPT_STATUS_OK;
308		} else {
309			if (spec->value)
310				*((char **)spec->value) = parser->args[parser->idx];
311	
312			parser->idx++;
313			opt->status = CLI_OPT_STATUS_OK;
314		}
315	
316		return opt->status;
317	}
