391	/*
392	 * Some parsers allow for handling arguments like "file1 --help file2";
393	 * this is done by re-sorting the arguments in-place; emulate that.
394	 */
395	static int sort_gnu_style(cli_opt_parser *parser)
396	{
397		size_t i, j, insert_idx = parser->idx, offset;
398		const cli_opt_spec *spec;
399		char *option, *value;
400		int needs_value, changed = 0;
401	
402		parser->needs_sort = 0;
403	
404		for (i = parser->idx; i < parser->args_len; i++) {
405			spec = spec_for_sort(&needs_value, parser, parser->args[i]);
406	
407			/* Not a "-" or "--" prefixed option.  No change. */
408			if (!spec)
409				continue;
410	
411			/* A "--" alone means remaining args are literal. */
412			if (spec->type == CLI_OPT_TYPE_LITERAL)
413				break;
414	
415			option = parser->args[i];
416	
417			/*
418			 * If the argument is a value type and doesn't already
419			 * have a value (eg "--foo=bar" or "-fbar") then we need
420			 * to copy the next argument as its value.
421			 */
422			if (spec->type == CLI_OPT_TYPE_VALUE && needs_value) {
423				/*
424				 * A required value is not provided; set parser
425				 * index to this value so that we fail on it.
426				 */
427				if (i + 1 >= parser->args_len) {
428					parser->idx = i;
429					return 1;
430				}
431	
432				value = parser->args[i + 1];
433				offset = 1;
434			} else {
435				value = NULL;
436				offset = 0;
437			}
438	
439			/* Caller error if args[0] is an option. */
440			if (i == 0)
441				return 0;
442	
443			/* Shift args up one (or two) and insert the option */
444			for (j = i; j > insert_idx; j--)
445				parser->args[j + offset] = parser->args[j - 1];
446	
447			parser->args[insert_idx] = option;
448	
449			if (value)
450				parser->args[insert_idx + 1] = value;
451	
452			insert_idx += (1 + offset);
453			i += offset;
454	
455			changed = 1;
456		}
457	
458		return changed;
459	}
