593		cli_opt opt;
594		int ret;
595	
596		cli_opt_parser_init(&parser, specs, args, args_len, flags);
597	
598		while (cli_opt_parser_next(&opt, &parser)) {
599			if ((ret = callback(&opt, callback_data)) != 0)
600				return ret;
601		}
602	
603		return 0;
604	}
