        /// only a parse writes.
        ///
        /// Wraps `st::cli_opt_spec`
        ///
        /// Wraps `tdf::cli_opt_spec`
        #[doc(alias = "cli_opt_spec")]
        Spec<'p>, SpecRef, SpecMut, sys::cli_opt_spec, phantom = Cell<&'p CStr>
    );

