2485	    /// use core::ops::ControlFlow;
2486	    /// use libgit2_crustify::git2::src::cli::opt::{ForeachCallbackFn, OptRef};
2487	    ///
2488	    /// fn keep<'k, 'p>(kept: &mut Option<OptRef<'k, 'p>>) {
2489	    ///     let mut f = |opt: OptRef<'_, 'p>| {
