3263	    /// `cli_opt_parser_init`: [`Parser::new`] over the table at `specs` and the `args_len`
3264	    /// arguments at `args`, written to `*parser`, which it overwrites whole, as C's `memset`
3265	    /// does. A panic aborts, as it cannot fail.
3266	    ///
3267	    /// The C stores `specs` and `args` unread, and the parse that follows reads them; here they
3268	    /// are read at once, so a `NULL` parser, a `NULL` table, a `NULL` array of arguments with
3269	    /// `args_len` other than 0, or a `NULL` argument within it aborts, where the C, built with
3270	    /// `NDEBUG`, writes through the `NULL` parser or faults in that parse.
3271	    ///
3272	    /// # Safety
3273	    ///
3274	    /// `parser` is valid for a write of a `cli_opt_parser`; `specs` is a spec table, as
3275	    /// [`SpecTable::from_ptr`] adopts one, and `args` addresses `args_len` arguments, each a
3276	    /// NUL-terminated string, unless `args_len` is 0: all of them live, the strings unchanged,
3277	    /// while C uses the parser, and nothing but that parse reaches the array meanwhile.
3278	    #[unsafe(no_mangle)]
3279	    unsafe extern "C" fn cli_opt_parser_init(
3280	        parser: *mut sys::cli_opt_parser,
3281	        specs: *const sys::cli_opt_spec,
3282	        args: *mut *mut c_char,
3283	        args_len: usize,
3284	        flags: c_uint,
3285	    ) {
3286	        if parser.is_null() {
3287	            std::process::abort();
3288	        }
3289	        // SAFETY: the caller's contract: `specs` is a table that lives, unchanged, while C uses
3290	        // the parser, the lifetime this adoption takes.
3291	        let Some(table) = (unsafe { SpecTable::from_ptr(specs) }) else {
3292	            std::process::abort();
3293	        };
3294	        let args: &mut [Arg<'_>] = if args_len == 0 {
3295	            &mut []
3296	        } else {
3297	            if args.is_null() {
3298	                std::process::abort();
3299	            }
3300	            // SAFETY: the caller's contract: `args` addresses `args_len` readable elements.
3301	            let elements = unsafe { slice::from_raw_parts(args.cast_const(), args_len) };
3302	            if elements.iter().any(|arg| arg.is_null()) {
3303	                std::process::abort();
3304	            }
3305	            // SAFETY: the `args_len` elements are non-null, as just checked, and each a
3306	            // NUL-terminated string that lives, unchanged, while C uses the parser, which only
3307	            // that parse reaches meanwhile, by the caller's contract: valid `Arg`s, which are
3308	            // `#[repr(transparent)]` over a non-null `char *`, borrowed exclusively for as long.
3309	            unsafe { slice::from_raw_parts_mut(args.cast::<Arg<'_>>(), args_len) }
3310	        };
3311	        let flags = ParseFlags::from_bits_retain(flags);
3312	        let new = barrier(|| Parser::new(table, args, flags), || std::process::abort());
3313	        // SAFETY: `parser` is non-null and valid for a write of a `cli_opt_parser`, the
3314	        // caller's contract; `Parser` is `#[repr(transparent)]` over it, and the write reads
3315	        // nothing of the old value, which needs no drop.
3316	        unsafe { parser.cast::<Parser<'_>>().write(new) };
3317	    }
