3319	    /// `cli_opt_status_fprint`: [`OptRef::write_status`] of `*opt` to the stream `file`, after
3320	    /// `command` when it is not `NULL`, read from the table that starts at the outcome's spec,
3321	    /// which holds that spec's later choices. Returns 0 once it is written, and -1 when a write
3322	    /// fails, as `opt.h` documents, `errno` holding the stream's error, or `EINVAL` for an
3323	    /// outcome the message cannot name, a missing value or argument with no spec, whose spec the
3324	    /// C reads through a null pointer. A panic is reported as a failure.
3325	    ///
3326	    /// The C returns the count of its last piece's `fprintf` on success: no caller reads it. A
3327	    /// `command` or an argument that is not UTF-8 is written with each invalid sequence replaced
3328	    /// by U+FFFD, since libc's wrapper writes text: [`FileWriter`]'s departure.
3329	    ///
3330	    /// # Safety
3331	    ///
3332	    /// `file` is an open stream that stays open during the call, every other access to it
3333	    /// holding its lock, as C's stdio routines do; `command` is `NULL` or a NUL-terminated
3334	    /// string; and `opt` is an outcome C's parser wrote, or a zeroed one: a valid `Opt`, as
3335	    /// [`Opt`](super::Opt)'s adoption asks, whose spec, when it has one, is an element of a spec
3336	    /// table [`SpecTable::from_ptr`] adopts from it. All of them live, unchanged, for the call.
3337	    #[unsafe(no_mangle)]
3338	    unsafe extern "C" fn cli_opt_status_fprint(
3339	        file: *mut sys::FILE,
3340	        command: *const c_char,
3341	        opt: *const sys::cli_opt,
3342	    ) -> c_int {
3343	        // SAFETY: the caller's contract: `file` is an open stream for the call, every other
3344	        // access holding its lock, as `FileRef::from_ptr` asks of a stream.
3345	        let Some(file) = (unsafe { FileRef::from_ptr(file) }) else {
3346	            set_errno(Errno::EINVAL as c_int);
3347	            return -1;
3348	        };
3349	        // SAFETY: the caller's contract: a non-null `command` is a NUL-terminated string that
3350	        // lives, unchanged, for the call.
3351	        let command = (!command.is_null()).then(|| unsafe { CStr::from_ptr(command) });
3352	        // SAFETY: the caller's contract: `opt` is a valid outcome that lives, unchanged, for
3353	        // the call, the lifetime this adoption takes.
3354	        let Some(opt) = (unsafe { OptRef::from_ptr(opt.cast_mut()) }) else {
3355	            set_errno(Errno::EINVAL as c_int);
3356	            return -1;
3357	        };
3358	        let end = [Spec::zeroed()];
3359	        let specs = opt
3360	            .spec()
3361	            // SAFETY: the caller's contract: the outcome's spec is an element of a table
3362	            // ended by a spec of kind `CLI_OPT_TYPE_NONE`, live and unchanged for the call.
3363	            .and_then(|spec| unsafe { SpecTable::from_ptr(spec.as_ptr()) })
3364	            .or_else(|| SpecTable::new(&end));
3365	        let Some(specs) = specs else {
3366	            set_errno(Errno::EINVAL as c_int);
3367	            return -1;
3368	        };
3369	        let command = command.map(CStr::to_string_lossy);
3370	        let written = barrier(
3371	            || opt.write_status(&mut FileWriter(file), command.as_deref(), specs),
3372	            || Err(std::io::Error::other("panicked")),
3373	        );
3374	        match written {
3375	            Ok(()) => 0,
3376	            Err(e) => {
3377	                // The stream's failures leave `errno` as `fprintf` set it; the refusal of an
3378	                // outcome without a spec sets none of its own.
3379	                if e.kind() == std::io::ErrorKind::InvalidInput && e.raw_os_error().is_none() {
3380	                    set_errno(Errno::EINVAL as c_int);
3381	                }
3382	                -1
3383	            }
3384	        }
3385	    }
3386	}
