    let mut parser = Parser::new(table, &mut args, ParseFlags::FORCE_GNU);
    let opt = parser.as_mut().parse_next();
    assert_eq!(opt.as_ref().value(), Some(c"out"));
    assert!(!parser.as_ref().needs_sort());
    assert_eq!(
        strings(parser.as_ref().args()),
