    let owned = heap(&["-d", "-", "x"]);
    let mut args: Vec<_> = owned.iter().map(|a| Arg::new(a)).collect();
    let specs = [
        Spec::new(Target::Value(None)).with_name(c"config-env"),
        Spec::new(Target::Bool(None)).with_alias(b'd'),
        Spec::zeroed(),
    ];
